"use client"

import dynamic from "next/dynamic"
import { useEffect, useState } from "react"
import { getStaticMapUrl } from "@/app/actions/static-map"

const MapComponent = dynamic(() => import("./map-component"), {
  ssr: false,
  loading: () => (
    <div className="w-full h-full rounded-md bg-muted flex items-center justify-center">
      <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
    </div>
  ),
})

interface StaticMapProps {
  lat: number
  lng: number
  label?: string
}

export default function StaticMap({ lat, lng, label }: StaticMapProps) {
  const [mapUrl, setMapUrl] = useState<string | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const fetchMapUrl = async () => {
      try {
        const url = await getStaticMapUrl(lat, lng)
        setMapUrl(url)
      } catch (error) {
        console.error("Failed to load map:", error)
      } finally {
        setLoading(false)
      }
    }

    fetchMapUrl()
  }, [lat, lng])

  if (loading) {
    return (
      <div className="w-full h-full rounded-md bg-muted flex items-center justify-center">
        <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin"></div>
      </div>
    )
  }

  if (!mapUrl) {
    return (
      <div className="w-full h-full rounded-md bg-muted flex items-center justify-center">
        <p className="text-xs text-muted-foreground px-2 text-center">Map unavailable</p>
      </div>
    )
  }

  return (
    <div className="w-full h-full rounded-md overflow-hidden">
      <MapComponent
        center={[lat, lng]}
        maintenancePins={[
          {
            id: "location",
            lat,
            lng,
            status: "pending",
            title: label || "Location",
          },
        ]}
        suggestionPins={[]}
        suggestionsVisible={false}
        onPinClick={() => {}}
        zoom={15}
      />
    </div>
  )
}
